  -- ── H.R. 4405 sponsorship (vr_positions) ──────────────────────────────────
  -- The Epstein Files Transparency Act passed 427-1 under suspension of the rules. That
  -- roll is a real, citable gov_transparency record for everyone who cast it, and it
  -- separates almost nobody. What separates is who put their name on the bill in July
  -- 2025, four months before the floor caught up: Rep. Ro Khanna as sponsor and Rep.
  -- Thomas Massie as ORIGINAL cosponsor (the bill's own isOriginalCosponsor flag, not an
  -- inference from the date). Twenty-four members cosponsored in all; these four are the
  -- ones db/vr-member-map.json resolves, and an unresolved cosponsor is skipped rather
  -- than guessed.
  IF m_119_h_r_4405 IS NOT NULL THEN
    INSERT INTO vr_positions (measure_id, politician_id, action_type, supports, acted_at, source_url, note) VALUES
      (m_119_h_r_4405, 'khanna', 'sponsor', true, TIMESTAMPTZ '2025-07-15T00:00:00Z',
       'https://www.congress.gov/bill/119th-congress/house-bill/4405/cosponsors', 'Lead sponsor. Introduced H.R. 4405 on 2025-07-15, four months before the House voted.'),
      (m_119_h_r_4405, 'massie', 'cosponsor', true, TIMESTAMPTZ '2025-07-15T00:00:00Z',
       'https://www.congress.gov/bill/119th-congress/house-bill/4405/cosponsors', 'ORIGINAL cosponsor (isOriginalCosponsor=True in the bill''s own record), joining on the day of introduction.'),
      (m_119_h_r_4405, 'omar', 'cosponsor', true, TIMESTAMPTZ '2025-07-17T00:00:00Z',
       'https://www.congress.gov/bill/119th-congress/house-bill/4405/cosponsors', 'Cosponsor, joined 2025-07-17.'),
      (m_119_h_r_4405, 'adam_smith', 'cosponsor', true, TIMESTAMPTZ '2025-07-23T00:00:00Z',
       'https://www.congress.gov/bill/119th-congress/house-bill/4405/cosponsors', 'Cosponsor, joined 2025-07-23.')
    ON CONFLICT (measure_id, politician_id, action_type) DO NOTHING;
  END IF;

  -- ── issue mappings ────────────────────────────────────────────────────────
  -- Curated in db/vr-issue-seed.json, with the provision-level rationale and a primary
  -- source on every row — scripts/test-mapping-discipline.mjs requires both.

  -- H.R. 29 (119th) — deportations yea_supports w100, border_security yea_supports w70, tough_on_crime yea_supports w55, states_federal_power yea_supports w40
  --   Byte-identical to what is already live (S. 5's four from migration 20260804000000,
  --   H.R. 29's four from an earlier pass). Re-emitted because db/vr-issue-seed.json carries
  --   these rows and the ingest endpoint re-asserts them; the ON CONFLICT below makes it a
  --   no-op against a database that already holds them.
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_h_r_29, 'deportations', 100, true, 'yea_supports',
      'Mandates detention and removal proceedings for covered unauthorized immigrants.',
      'https://www.congress.gov/bill/119th-congress/house-bill/29'),
    (m_119_h_r_29, 'border_security', 70, false, 'yea_supports',
      'Tightens immigration enforcement.',
      'https://www.congress.gov/bill/119th-congress/house-bill/29'),
    (m_119_h_r_29, 'tough_on_crime', 55, false, 'yea_supports',
      'Section 2 of the bill as passed the House adds a new INA 236(c)(1)(E) requiring the Secretary of Homeland Security to detain an inadmissible alien charged with, arrested for, convicted of, or who admits having committed burglary, theft, larceny or shoplifting, and to issue a detainer and take custody. A yea attaches a mandatory custodial consequence to those offences. Weighted 55, identical to S. 5''s mapping, so the two Laken Riley vehicles score the same axis at the same strength. Note the House bill reaches ONLY those four property offences: assault of a law enforcement officer and crimes resulting in death or serious bodily injury entered the statute later, through the Senate''s S.Amdt. 14 and S.Amdt. 8.',
      'https://www.govinfo.gov/content/pkg/BILLS-119hr29eh/html/BILLS-119hr29eh.htm'),
    (m_119_h_r_29, 'states_federal_power', 40, false, 'yea_supports',
      'Section 3, ''Enforcement by attorney general of a State'', amends INA 235(b) (8 U.S.C. 1225(b)) to give the attorney general of a State, or another authorised State officer, standing to sue the Secretary of Homeland Security in federal district court over alleged violations of the detention and removal requirements that harm the State or its residents. A yea creates a state cause of action against the federal government. Weighted 40, identical to S. 5''s mapping. The same section is what the Senate''s S.Amdt. 23 tried and failed to strike.',
      'https://www.govinfo.gov/content/pkg/BILLS-119hr29eh/html/BILLS-119hr29eh.htm')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- S. 5 (119th) — deportations yea_supports w100, border_security yea_supports w70, tough_on_crime yea_supports w55, states_federal_power yea_supports w40
  --   Byte-identical to what is already live (S. 5's four from migration 20260804000000,
  --   H.R. 29's four from an earlier pass). Re-emitted because db/vr-issue-seed.json carries
  --   these rows and the ingest endpoint re-asserts them; the ON CONFLICT below makes it a
  --   no-op against a database that already holds them.
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_s_5, 'deportations', 100, true, 'yea_supports',
      'Mandates detention and removal proceedings for covered unauthorized immigrants.',
      'https://www.congress.gov/bill/119th-congress/senate-bill/5'),
    (m_119_s_5, 'border_security', 70, false, 'yea_supports',
      'Tightens immigration enforcement.',
      'https://www.congress.gov/bill/119th-congress/senate-bill/5'),
    (m_119_s_5, 'tough_on_crime', 55, false, 'yea_supports',
      'Triggered by arrest for burglary, theft, larceny, shoplifting, assault of a law enforcement officer, or any crime resulting in death or serious bodily injury.',
      'https://www.congress.gov/bill/119th-congress/senate-bill/5'),
    (m_119_s_5, 'states_federal_power', 40, false, 'yea_supports',
      'Gives state attorneys general standing to sue the federal government over certain immigration-detention and enforcement decisions; a yea expands state authority to contest federal enforcement choices in court.',
      'https://www.congress.gov/bill/119th-congress/senate-bill/5')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- S. 1071 (119th) — strong_defense yea_supports w80, immig_fentanyl yea_supports w40, states_federal_power yea_supports w25
  --   Applied to EVERY row carrying this number — one row today (id 75). Written as a loop
  --   because (congress, number) is not unique, so a duplicate added later is covered too.
  FOR mid IN SELECT id FROM vr_measures WHERE congress = 119 AND number = 'S. 1071' LOOP
    INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
      (mid, 'strong_defense', 80, true, 'yea_supports',
        'The annual defence authorisation: Divisions A through H authorise Department of Defense military activities, military construction, Department of Energy national security programs, personnel strengths and the Intelligence Authorization Act for Fiscal Year 2026. A yea authorises and equips the armed forces. Weighted 80 rather than 100 for the same reason as the FY2027 NDAA (H.R. 8800): the enacted text folds in fourteen separately titled Acts, several unrelated to defence posture, so passage is not a pure defence-posture signal.',
        'https://www.govinfo.gov/content/pkg/BILLS-119s1071enr/html/BILLS-119s1071enr.htm'),
      (mid, 'immig_fentanyl', 40, false, 'yea_supports',
        'Division H, Title LXXXIII, Subtitle B (Secs. 8311-8314) is the Break Up Suspicious Transactions of Fentanyl Act — the BUST Fentanyl Act — enacted through this vehicle: it amends the Fentanyl Sanctions Act, adds fentanyl-trafficking reporting to the International Narcotics Control Strategy Report, and requires a study and report on fentanyl trafficking originating in the People''s Republic of China. A yea enacts new sanctions authority and reporting aimed at fentanyl traffickers. Weighted 40 on purpose: it is one named subtitle inside an omnibus, and it works through sanctions and reporting rather than a direct enforcement change.',
        'https://www.govinfo.gov/content/pkg/BILLS-119s1071enr/html/BILLS-119s1071enr.htm'),
      (mid, 'states_federal_power', 25, false, 'yea_supports',
        'Section 512 inserts a new 32 U.S.C. 328a: the chief executive of a State that has declared an emergency due to a disaster may order a member of that State''s National Guard who is serving on Active Guard and Reserve duty to perform State disaster-response duty. A yea hands a governor direct authority over federally paid Guard personnel. Weighted 25 — the lowest mapping in this pass — because the authority is gated on the Secretary of Defense''s consent, is reimbursable by the State, and is capped at 14 days per member per calendar year (extendable by 7 days, or by 46 for a catastrophic incident). It is a real Title 32 shift toward the states, but it is one narrow section of a 312-112 defence authorisation and must not be read as a federalism referendum.',
        'https://www.govinfo.gov/content/pkg/BILLS-119s1071enr/html/BILLS-119s1071enr.htm')
    ON CONFLICT (measure_id, issue_key) DO NOTHING;
  END LOOP;

  -- S.Amdt. 14 (119th) — deportations yea_supports w100, tough_on_crime yea_supports w70
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_s_amdt_14, 'deportations', 100, true, 'yea_supports',
      'Amendment to S. 5 (Laken Riley Act) whose stated purpose is ''To expand the list of criminal offenses that subject inadmissible aliens to mandatory detention.'' A yea widens the set of people the Secretary of Homeland Security must take into custody and place in removal proceedings. Agreed to 70-25 and carried into Public Law 119-1, so this is enacted text and not a message vote.',
      'https://www.senate.gov/legislative/LIS/roll_call_votes/vote1191/vote_119_1_00003.htm'),
    (m_119_s_amdt_14, 'tough_on_crime', 70, false, 'yea_supports',
      'The operative change is to the LIST OF CRIMINAL OFFENCES that triggers the detention mandate, so a yea attaches a mandatory custodial consequence to a broader set of crimes. Weighted above S. 5''s own tough_on_crime mapping (55) rather than below it: the bill does many things and this amendment does only this one, so the crime-severity axis is a larger share of what a senator was voting on.',
      'https://www.senate.gov/legislative/LIS/roll_call_votes/vote1191/vote_119_1_00003.htm')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- S.Amdt. 23 (119th) — states_federal_power yea_opposes w100
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_s_amdt_23, 'states_federal_power', 100, true, 'yea_opposes',
      'Amendment to S. 5 (Laken Riley Act) whose stated purpose is ''To strike the section that authorizes State attorneys general to sue Federal immigration authorities for alleged violations relating to the detention of aliens.'' A YEA REMOVES a state cause of action against the federal government, so a yea cuts against keeping decisions and remedies with the states — the mirror of S. 5''s own states_federal_power mapping, which is yea_supports because passing the bill is what created the standing. Rejected 46-49, so the section survived into Public Law 119-1.',
      'https://www.senate.gov/legislative/LIS/roll_call_votes/vote1191/vote_119_1_00004.htm')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- S.Amdt. 8 (119th) — deportations yea_supports w100, tough_on_crime yea_supports w75
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_s_amdt_8, 'deportations', 100, true, 'yea_supports',
      'Amendment to S. 5 (Laken Riley Act) whose stated purpose is ''To include crimes resulting in death or serious bodily injury to the list of offenses that, if committed by an inadmissible alien, require mandatory detention.'' A yea widens the set of people the Secretary of Homeland Security must take into custody and place in removal proceedings. Agreed to 75-24 and carried into Public Law 119-1.',
      'https://www.senate.gov/legislative/LIS/roll_call_votes/vote1191/vote_119_1_00006.htm'),
    (m_119_s_amdt_8, 'tough_on_crime', 75, false, 'yea_supports',
      'The offences this amendment adds are defined by their RESULT — death or serious bodily injury — rather than by category, so it is the most direct crime-severity test in the bill''s whole floor consideration. H.R. 29 as passed the House and S. 5 as introduced reached only burglary, theft, larceny and shoplifting; this is where the death-or-serious-injury trigger enters the statute. A yea attaches mandatory detention to the gravest offences on the list.',
      'https://www.senate.gov/legislative/LIS/roll_call_votes/vote1191/vote_119_1_00006.htm')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.R. 4405 (119th) — gov_transparency yea_supports w100
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_h_r_4405, 'gov_transparency', 100, true, 'yea_supports',
      'Requires the Department of Justice to publish, in a searchable and downloadable format, all unclassified records relating to the investigation and prosecution of Jeffrey Epstein — including materials relating to Ghislaine Maxwell, flight logs and travel records, and the individuals named or referenced, government officials among them — and to report to Congress within 15 days the categories released and withheld, a summary of redactions, and a list of the government officials and politically exposed individuals named. A yea compels disclosure the executive branch had withheld. This is the whole substance of the Act: it creates no offence and changes no penalty, so gov_transparency carries it alone.',
      'https://www.congress.gov/bill/119th-congress/house-bill/4405')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

END $$;

-- ---------------------------------------------------------------------------
-- Verification
-- ---------------------------------------------------------------------------
-- Read-only, and scoped by tuple to exactly this pass's roll calls and measures so it
-- can only ever fail on data this migration is responsible for. A global count would
-- drag in every immigration and defence mapping earlier passes wrote and stop meaning
-- anything.
--
-- Mapping counts assert >= rather than =, because three of this pass's measures already
-- carried the exact mappings it re-emits — S. 5 has four from migration 20260804000000,
-- H.R. 29 has four from an earlier pass, and the descriptive 'Senate Amendment to S. 5'
-- row has two — and because the S. 1071 mapping is written by a loop over every row with
-- that number. The S. 1071 check is therefore stated the other way round: NO row
-- numbered S. 1071 may be left without the strong_defense mapping. Member-vote counts
-- assert >= for the same class of reason — three of the nine rolls were already live,
-- senate 119/1/7 with 83 attributed votes against this seed's 39, so an existing roll
-- legitimately holds more than the seed carries.
--
-- The orphan check is scoped to the six rolls this pass CREATED. The three that were
-- already live are excluded: house 119/1/6, house 119/1/23 and senate 119/1/7 hold
-- pre-existing member votes that came through an earlier and wider attribution path, and
-- failing on those would be failing on somebody else's data.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  n_rolls integer;
  n_votes integer;
  n_orphan integer;
  n_issues integer;
  n_pos integer;
  n_parent integer;
  n_ndaa_unmapped integer;
  n_h23 integer;
BEGIN
  WITH want (chamber, congress, session, roll_number) AS (VALUES
    ('house'::text, 119::integer, 1::integer, 6::integer),
    ('senate'::text, 119::integer, 1::integer, 3::integer),
    ('senate'::text, 119::integer, 1::integer, 4::integer),
    ('senate'::text, 119::integer, 1::integer, 6::integer),
    ('senate'::text, 119::integer, 1::integer, 7::integer),
    ('house'::text, 119::integer, 1::integer, 23::integer),
    ('house'::text, 119::integer, 1::integer, 289::integer),
    ('house'::text, 119::integer, 1::integer, 320::integer),
    ('senate'::text, 119::integer, 1::integer, 648::integer)
  ), roll_ids AS (
    SELECT r.id FROM vr_rollcalls r JOIN want w
      ON r.chamber = w.chamber AND r.congress = w.congress
     AND r.session = w.session AND r.roll_number = w.roll_number
  ), fresh (chamber, congress, session, roll_number) AS (VALUES
    ('senate'::text, 119::integer, 1::integer, 3::integer),
    ('senate'::text, 119::integer, 1::integer, 4::integer),
    ('senate'::text, 119::integer, 1::integer, 6::integer),
    ('senate'::text, 119::integer, 1::integer, 648::integer),
    ('house'::text, 119::integer, 1::integer, 289::integer),
    ('house'::text, 119::integer, 1::integer, 320::integer)
  ), fresh_ids AS (
    SELECT r.id FROM vr_rollcalls r JOIN fresh f
      ON r.chamber = f.chamber AND r.congress = f.congress
     AND r.session = f.session AND r.roll_number = f.roll_number
  ), mine (congress, chamber, number) AS (VALUES
    (119::integer, 'house'::text, 'H.R. 29'::text),
    (119::integer, 'senate'::text, 'S. 5'::text),
    (119::integer, 'senate'::text, 'S. 1071'::text),
    (119::integer, 'senate'::text, 'S.Amdt. 14'::text),
    (119::integer, 'senate'::text, 'S.Amdt. 23'::text),
    (119::integer, 'senate'::text, 'S.Amdt. 8'::text),
    (119::integer, 'house'::text, 'H.R. 4405'::text)
  ), measure_ids AS (
    SELECT m.id FROM vr_measures m JOIN mine k
      ON m.congress = k.congress AND m.chamber = k.chamber AND m.number = k.number
  )
  SELECT (SELECT count(*) FROM roll_ids),
         (SELECT count(*) FROM vr_member_votes v WHERE v.rollcall_id IN (SELECT id FROM roll_ids)),
         (SELECT count(*) FROM vr_member_votes v WHERE v.rollcall_id IN (SELECT id FROM fresh_ids)
            AND v.politician_id NOT IN (
              'adam_smith', 'andy_kim', 'aoc', 'barrasso', 'bennie_thompson', 'bmoore', 'boebert', 'booker', 'brian_mast', 'britt', 'bruce_westerman', 'chris_murphy', 'collins', 'crockett', 'cruz', 'cstewart', 'curtis', 'dan_goldman', 'don_bacon', 'don_davis', 'durbin', 'emmer', 'ernst', 'fetterman', 'frank_lucas', 'french_hill', 'gaetz', 'gallego', 'graham', 'grassley', 'greg_landsman', 'haley_stevens', 'hawley', 'jake_auchincloss', 'jason_smith', 'jayapal', 'jeffries', 'jim_jordan', 'john_cornyn', 'jon_ossoff', 'josh_brecheen', 'josh_gottheimer', 'julie_fedorchak', 'kaine', 'kclark', 'kennedy', 'kennedy_john', 'khanna', 'lankford', 'lee', 'mariannette_miller_meeks', 'mark_kelly', 'massie', 'maxine_waters', 'mcconnell', 'meeks', 'michael_guest', 'mike_collins', 'mike_ezell', 'mike_flood', 'mike_johnson', 'mike_lawler', 'mike_simpson', 'mike_waltz', 'mtg', 'murkowski', 'omar', 'owens', 'rand_paul', 'reed', 'rick_crawford', 'risch', 'rob_bresnahan', 'rosen', 'rubio', 'ryan_mackenzie', 'sanders', 'scalise', 'schiff', 'schumer', 'scott_perry', 'shaheen', 'slotkin', 'stefanik', 'steny_hoyer', 'stephanie_bice', 'steve_womack', 'summer_lee', 'tgabbard', 'thune', 'tim_scott', 'tlaib', 'tom_cole', 'tom_suozzi', 'torres', 'trent_kelly', 'troy_downing', 'van_hollen', 'warnock', 'warren', 'zeldin'
            )),
         (SELECT count(*) FROM vr_measure_issues i WHERE i.measure_id IN (SELECT id FROM measure_ids)
            AND i.issue_key IN ('border_security', 'deportations', 'gov_transparency', 'immig_fentanyl', 'states_federal_power', 'strong_defense', 'tough_on_crime')),
         (SELECT count(*) FROM vr_positions p
           WHERE p.measure_id IN (SELECT id FROM measure_ids) AND p.action_type IN ('sponsor', 'cosponsor')),
         (SELECT count(*) FROM vr_measures a JOIN vr_measures p ON p.id = a.parent_id
           WHERE a.congress = 119 AND a.chamber = 'senate'
             AND a.number IN ('S.Amdt. 8', 'S.Amdt. 14', 'S.Amdt. 23')
             AND p.congress = 119 AND p.chamber = 'senate' AND p.number = 'S. 5'),
         (SELECT count(*) FROM vr_measures m WHERE m.congress = 119 AND m.number = 'S. 1071'
            AND NOT EXISTS (SELECT 1 FROM vr_measure_issues i
                             WHERE i.measure_id = m.id AND i.issue_key = 'strong_defense')),
         (SELECT count(*) FROM vr_member_votes v JOIN vr_rollcalls r ON r.id = v.rollcall_id
           WHERE r.chamber = 'house' AND r.congress = 119 AND r.session = 1 AND r.roll_number = 23)
    INTO n_rolls, n_votes, n_orphan, n_issues, n_pos, n_parent, n_ndaa_unmapped, n_h23;

  RAISE NOTICE 'Landmark pass: % roll calls, % member votes, % issue mappings, % sponsorship rows', n_rolls, n_votes, n_issues, n_pos;
  RAISE NOTICE 'Landmark pass: house 119/1/23 (S. 5, On Passage) now carries % attributed member votes', n_h23;

  IF n_rolls <> 9 THEN
    RAISE EXCEPTION 'Landmark pass: expected 9 roll calls, found %', n_rolls;
  END IF;
  IF n_votes < 423 THEN
    RAISE EXCEPTION 'Landmark pass: expected at least 423 member votes on these roll calls, found %', n_votes;
  END IF;
  IF n_orphan > 0 THEN
    RAISE EXCEPTION 'Landmark pass: % member vote(s) on the rolls this pass created carry a politician_id outside db/vr-member-map.json', n_orphan;
  END IF;
  IF n_issues < 17 THEN
    RAISE EXCEPTION 'Landmark pass: expected at least 17 issue mappings on this pass''s measures, found %', n_issues;
  END IF;
  IF n_pos < 4 THEN
    RAISE EXCEPTION 'Landmark pass: expected at least 4 H.R. 4405 sponsorship rows, found %', n_pos;
  END IF;
  IF n_parent <> 3 THEN
    RAISE EXCEPTION 'Landmark pass: expected all 3 Laken Riley amendments linked to their S. 5 parent, found % link(s)', n_parent;
  END IF;
  IF n_ndaa_unmapped > 0 THEN
    RAISE EXCEPTION 'Landmark pass: % row(s) numbered S. 1071 carry no strong_defense mapping', n_ndaa_unmapped;
  END IF;
  IF n_h23 < 57 THEN
    RAISE EXCEPTION 'Landmark pass: house 119/1/23 was not topped up — only % member votes', n_h23;
  END IF;
END $$;
